window.RP_SESSION={"id":"S-952f0184ea22","messages":[{"id":"RP-0155554","time":"2026-05-12T01:45:00+09:00","room":"RP","name":"솔 세크메트","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"··· 응어리진 남색 빛의 하늘. 구름이 몽글몽글 일렁이며 지나가고. 솔은 찢겨진 천막의 구멍 사이로 그것을 바라보다가.\n\n부스럭거리는 소리를 내며 일어났다. 잠깐 손으로 구멍을 막고, 아래 두었던 나무 양동이에 찬 빗물을 버리고, 다시 내려놓고···.\n\n그리고는 이불을 옆으로 넘기고. 비 흐르는 바깥으로 향했다. 반딧불이가 모여 일렁이는 불빛을 만들어내고 있었다.","characters":["P-e2f54d3db7fa"]},{"id":"RP-0155555","time":"2026-05-12T01:46:00+09:00","room":"RP","name":"솔 세크메트","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"옆에 쪼그려 앉아, 꽃을 빤히 바라보았다.\n\n이 근처에서 마리우스를 찾는 사람을 많이 보았다. 여기가 비밀장소기는 한 걸까.","characters":["P-e2f54d3db7fa"]},{"id":"RP-0155556","time":"2026-05-12T01:50:00+09:00","room":"RP","name":"솔 세크메트","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"걔는 무슨···. 하루에 세 네명이 왕복하는 장소를 비밀장소라고. 별종스러운 단생종이다.\n\n한숨을 내쉬고 빗물 가득 담은 꽃을 가볍게 톡톡 쳤다.","characters":["P-e2f54d3db7fa"]},{"id":"RP-0155557","time":"2026-05-12T07:13:00+09:00","room":"RP","name":"솔 세크메트","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-e2f54d3db7fa"]},{"id":"RP-0155558","time":"2026-05-12T07:13:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
